targets.expr:
WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  heap = max by (namespace, pod, container) (
    jvm_memory_used_bytes{area="heap", id="", namespace="$namespace"}
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  heap
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  nonheap = max by (namespace, pod, container) (
    jvm_memory_used_bytes{area="nonheap", id="", namespace="$namespace"}
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  nonheap
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  heap = max by (namespace, pod, container) (jvm_memory_used_bytes{area="heap", id="", namespace="$namespace"}),
  nonheap = max by (namespace, pod, container) (jvm_memory_used_bytes{area="nonheap", id="", namespace="$namespace"}),
  working_set = max by (namespace, pod, container) (
    container_memory_working_set_bytes{namespace="$namespace", container!="", container!="POD"}
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  clamp_min(
    working_set
    - on (namespace, pod, container) heap
    - on (namespace, pod, container) nonheap,
    0
  )
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  working_set = max by (namespace, pod, container) (
    container_memory_working_set_bytes{namespace="$namespace", container!="", container!="POD"}
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  working_set
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  max by (namespace, pod, container) (
    kube_pod_container_resource_requests{namespace="$namespace", resource="memory", unit="byte"}
  )
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

max by (namespace, workload_kind, workload_name, container) (
  kompass_rs_recommendations{
    namespace="$namespace",
    workload_name="$workload",
    resource_type="memory",
    resource_source="desired",
    mode="live"
  }
)
and on (namespace, workload_name, container) max by (namespace, workload_name, container) (
  kompass_pod_info{namespace="$namespace", workload_name="$workload", status="running"}
  and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  max by (namespace, pod, container) (
    kube_pod_container_resource_limits{namespace="$namespace", resource="memory", unit="byte"}
  )
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  xmx = max by (namespace, pod, container) (jvm_memory_bytes_max{area="heap", id="", namespace="$namespace"})
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  xmx
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    last_over_time(
      kompass_pod_info{namespace="$namespace", workload_name="$workload", status="running"}[$jvm_formula_lookback]
    )
    and on (namespace, pod, container) max by (namespace, pod, container) (
      last_over_time(jvm_info{namespace="$namespace"}[$jvm_formula_lookback])
    )
  ),
  heap = max by (namespace, pod, container) (
    jvm_memory_used_bytes{area="heap", id="", namespace="$namespace"}
  ),
  heap_p95 = quantile_over_time(0.95, heap[$jvm_formula_lookback:$jvm_formula_step]),
  calculated_xmx = clamp_min(
    ceil((heap_p95 * (100 + $jvm_gc_buffer_percent) / 100) / 1048576) * 1048576,
    $jvm_xms_bytes
  )
)
max by (namespace, resource_id, workload_kind, workload_name, container) (
  calculated_xmx
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  gc_by_pod = (
    sum by (namespace, pod, container) (
      max without (job, instance) (
        rate(
          jvm_gc_collection_seconds_sum{gc!="ZGC Pauses", namespace="$namespace"}[$jvm_gc_lookback]
        )
      )
    )
  )
)
clamp_max(
  clamp_min(
    max by (namespace, resource_id, workload_kind, workload_name, container) (
      gc_by_pod
      * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
    ),
    0
  ),
  1
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  pause_by_pod = (
    sum by (namespace, pod, container) (
      max without (job, instance) (
        rate(
          jvm_gc_collection_seconds_sum{gc="ZGC Pauses", namespace="$namespace"}[$jvm_gc_lookback]
        )
      )
    )
  )
)
clamp_max(
  clamp_min(
    max by (namespace, resource_id, workload_kind, workload_name, container) (
      pause_by_pod
      * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
    ),
    0
  ),
  1
)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  cpu_by_pod = max by (namespace, pod, container) (
    rate(
      container_cpu_usage_seconds_total{namespace="$namespace", container!="", container!="POD"}[1m]
    )
  ),
  cpu = cpu_by_pod
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)
max by (namespace, resource_id, workload_kind, workload_name, container) (cpu)

WITH (
  identity = max by (namespace, pod, container, resource_id, workload_kind, workload_name) (
    kompass_pod_info{namespace="$namespace", workload_name="$workload", pod=~"$replica", status="running"}
    and on (namespace, pod, container) max by (namespace, pod, container) (jvm_info{namespace="$namespace"})
  ),
  cpu_limit_by_pod = max by (namespace, pod, container) (
    kube_pod_container_resource_limits{namespace="$namespace", container!="", container!="POD", resource="cpu", unit="core"}
  ),
  cpu_limit = cpu_limit_by_pod
  * on (namespace, pod, container) group_left (resource_id, workload_kind, workload_name) identity
)
max by (namespace, resource_id, workload_kind, workload_name, container) (cpu_limit)
